import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"', strict=False)
    records = []

    try:
        for record in reader:
            records.append(record)
    except csv.Error:
        pass

    header_index = None
    columns = []

    for index, record in enumerate(records):
        normalized = [cell.strip().lstrip("\ufeff").casefold() for cell in record]
        if "nct_id" in normalized and "outcome_text" in normalized:
            header_index = index
            columns = [cell.lstrip("\ufeff") for cell in record]
            break

    if header_index is None:
        for index, record in enumerate(records):
            if record and any(cell.strip() for cell in record):
                header_index = index
                columns = [cell.lstrip("\ufeff") for cell in record]
                break

    if header_index is None:
        return {"columns": [], "rows": []}

    width = len(columns)
    if width == 0:
        return {"columns": [], "rows": []}

    normalized_columns = [column.strip().casefold() for column in columns]
    text_index = next(
        (
            index
            for index, name in enumerate(normalized_columns)
            if "outcome_text" in name or "description" in name or "text" in name
        ),
        min(1, width - 1),
    )

    rows = []
    for record in records[header_index + 1:]:
        if not record or not any(cell.strip() for cell in record):
            continue

        row = list(record)
        if len(row) > width:
            excess = len(row) - width
            end = min(len(row), text_index + excess + 1)
            row = (
                row[:text_index]
                + [",".join(row[text_index:end])]
                + row[end:]
            )
        if len(row) < width:
            row.extend([""] * (width - len(row)))
        elif len(row) > width:
            row = row[:width]

        rows.append(row)

    return {"columns": columns, "rows": rows}
